        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    protected int rowCount(String table) {
        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM " + table, Integer.class);
        return count == null ? 0 : count;
    }
}

